window.ScripturaLexicons.BDAG_PART_0386 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0386-01\" data-source=\"BDAG\" data-search=\"χείρ, χειρός, ἡ substantivo feminino mão; braço; agente; poder BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χείρ, χειρός, ἡ</td><td>substantivo feminino</td><td>mão; braço; agente; poder</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0386-02\" data-source=\"BDAG\" data-search=\"χειραγωγέω verbo conduzir pela mão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χειραγωγέω</td><td>verbo</td><td>conduzir pela mão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0386-03\" data-source=\"BDAG\" data-search=\"χειραγωγός, οῦ, ὁ substantivo masculino guia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χειραγωγός, οῦ, ὁ</td><td>substantivo masculino</td><td>guia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0386-04\" data-source=\"BDAG\" data-search=\"χειρόγραφον, ου, τό substantivo neutro documento manuscrito; registro de dívidas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χειρόγραφον, ου, τό</td><td>substantivo neutro</td><td>documento manuscrito; registro de dívidas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0386-05\" data-source=\"BDAG\" data-search=\"χειροποίητος, ον adjetivo; substantivado feito por mãos humanas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χειροποίητος, ον</td><td>adjetivo; substantivado</td><td>feito por mãos humanas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0386-06\" data-source=\"BDAG\" data-search=\"χειροτονέω verbo eleger; nomear BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χειροτονέω</td><td>verbo</td><td>eleger; nomear</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0386-07\" data-source=\"BDAG\" data-search=\"χειροτονία, ας, ἡ substantivo feminino gesto de desprezo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χειροτονία, ας, ἡ</td><td>substantivo feminino</td><td>gesto de desprezo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0386-08\" data-source=\"BDAG\" data-search=\"χείρων, ον, gen. ονος adjetivo comparativo pior; mais grave BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χείρων, ον, gen. ονος</td><td>adjetivo comparativo</td><td>pior; mais grave</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0386-09\" data-source=\"BDAG\" data-search=\"Χερούβ, τό / ὁ Χερουβίν Χερουβείν Χερουβείμ Χερουβίμ Χερουβεῖς substantivo indeclinável querubim; criatura alada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Χερούβ, τό / ὁ</td><td>substantivo indeclinável</td><td>querubim; criatura alada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0386-10\" data-source=\"BDAG\" data-search=\"χερσόω χερσόομαι verbo tornar seco; tornar-se estéril BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χερσόω</td><td>verbo</td><td>tornar seco; tornar-se estéril</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0386-11\" data-source=\"BDAG\" data-search=\"χέω χέομαι verbo derramar-se; jorrar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χέω</td><td>verbo</td><td>derramar-se; jorrar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0386-12\" data-source=\"BDAG\" data-search=\"χήρα, ας, ἡ substantivo feminino viúva BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χήρα, ας, ἡ</td><td>substantivo feminino</td><td>viúva</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0386-13\" data-source=\"BDAG\" data-search=\"χηρεία, ας, ἡ substantivo feminino viuvez BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χηρεία, ας, ἡ</td><td>substantivo feminino</td><td>viuvez</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0386-14\" data-source=\"BDAG\" data-search=\"χηρεύω verbo enviuvar; estar viúvo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χηρεύω</td><td>verbo</td><td>enviuvar; estar viúvo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0386-15\" data-source=\"BDAG\" data-search=\"χηροσύνη substantivo feminino viuvez BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χηροσύνη</td><td>substantivo feminino</td><td>viuvez</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0386-16\" data-source=\"BDAG\" data-search=\"χθές advérbio ontem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χθές</td><td>advérbio</td><td>ontem</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0386-17\" data-source=\"BDAG\" data-search=\"χιϚ´ sinal numérico; remissão ver χξϚ´ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χιϚ´</td><td>sinal numérico; remissão</td><td>ver χξϚ´</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0386-18\" data-source=\"BDAG\" data-search=\"χιλίαρχος, ου, ὁ / χιλιάρχης, ου, ὁ substantivo masculino tribuno militar; comandante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χιλίαρχος, ου, ὁ / χιλιάρχης, ου, ὁ</td><td>substantivo masculino</td><td>tribuno militar; comandante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0386-19\" data-source=\"BDAG\" data-search=\"χιλιάς, άδος, ἡ substantivo feminino milhar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χιλιάς, άδος, ἡ</td><td>substantivo feminino</td><td>milhar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0386-20\" data-source=\"BDAG\" data-search=\"χίλιοι, αι, α numeral cardinal mil BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χίλιοι, αι, α</td><td>numeral cardinal</td><td>mil</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0386-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χείρ, χειρός, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χείρ</span>, <span class=\"greek\">χειρός</span>, <span class=\"greek\">ἡ</span> (Hom.+); sobre a forma acus. <span class=\"greek\">χεῖραν</span> J 20:25 v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:6</a> v.l.; GJs 15:4 23:2 v. JPsichari, Essai sur le Grec de la Septante 1908, 164–70. Exemplos dos pap no Hdb. em J 20:25. Acus. dual <span class=\"greek\">τὼ</span> <span class=\"greek\">χεῖρε</span> somente Tat. 22, 1. Dat. <span class=\"greek\">χειροῖν</span> ApcPt Rainer ‘mão’.</p><p class=\"entry-text\">① lit. Mt 12:10; Mk 3:1; Lk 6:6, 8; Ac 12:7; 20:34 e outros lugares; AcPlCor 2:35. <span class=\"greek\">πόδες</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">χεῖρες</span> Mt 22:13; cf. Lk 24:39, 40; Ac 21:11a. Com outras partes do corpo no sing. e pl. Mt 5:(29), 30; 18:8ab, (9); J 11:44. No gen. com os verbos <span class=\"greek\">ἅπτομαι</span> Mt 8:15; <span class=\"greek\">ἐπιλαμβάνομαι</span> (v. esse verbete 1); <span class=\"greek\">κρατέω</span> (v. esse verbete 3b). No acus. com os verbos <span class=\"greek\">αἴρω</span> (v. esse verbete 1a); <span class=\"greek\">ἀπονίπτομαι</span> (v. esse verbete); <span class=\"greek\">βάλλω</span> J 20:25b; <span class=\"greek\">δέω</span> (v. esse verbete 1b); <span class=\"greek\">δίδωμι</span> (v. esse verbete 2); <span class=\"greek\">ἐκπετάννυμι</span> (v. esse verbete); <span class=\"greek\">ἐκτείνω</span> (v. esse verbete 1); <span class=\"greek\">ἐπαίρω</span> (v. esse verbete 1); <span class=\"greek\">ἐπιβάλλω</span> (v. esse verbete 1b); <span class=\"greek\">ἐπισείω</span> (v. esse verbete 1); <span class=\"greek\">ἐπιτίθημι</span> (v. esse verbete 1a<span class=\"greek\">α</span>; v. New Docs 4, 248 sobre a imposição de mãos; JCoppens, L’imposition des mains dans les Actes des Apôtres: Les Actes des Apôtres, ed. JKremer ’79, 405–38); cf. <span class=\"greek\">ἐπίθεσις</span> (<span class=\"greek\">τῶν</span>) <span class=\"greek\">χειρῶν</span> (v. <span class=\"greek\">ἐπίθεσις</span>); <span class=\"greek\">κατασείω</span> (v. esse verbete); <span class=\"greek\">νίπτομαι</span> (v. <span class=\"greek\">νίπτω</span> 1b<span class=\"greek\">β</span> e a literatura s.v. <span class=\"greek\">βαπτίζω</span> 1; também JDöller, Das rituelle Händewaschen bei den Juden: Theol.-prakt. Quartalschr. 64, 1911, 748–58); <span class=\"greek\">τίθημι</span> (v. esse verbete 1a<span class=\"greek\">β</span>); <span class=\"greek\">ποιεῖν</span>: <span class=\"greek\">ὀπίσω</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">χεῖρας</span> (<span class=\"greek\">ὀπίσω</span> 1a<span class=\"greek\">β</span>) e <span class=\"greek\">τὰς</span> <span class=\"greek\">χ</span>. <span class=\"greek\">ἐναλλάξ</span> (v. <span class=\"greek\">ἐναλλάξ</span>); <span class=\"greek\">προσφέρω</span> (v. esse verbete 1b<span class=\"greek\">β</span>).—No dat. instrumental <span class=\"greek\">ἔγραψα</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐμῇ</span> <span class=\"greek\">χειρί</span> (cf. Chariton 8, 4, 6; BGU 326 II, 2 e outros lugares nos pap.—<span class=\"greek\">χείρ</span>=caligrafia já em Hyperides em Pollux 2, 152, também Philod., <span class=\"greek\">π</span>. <span class=\"greek\">ποιημ</span>. 4, 33; 6, 14 Jens.; PMagd 25, 2 [III a.C.]; Jos., Ant. 14, 52) Gal 6:11; Phlm 19. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀσπασμὸς</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐμῇ</span> <span class=\"greek\">χειρί</span> (isto é, <span class=\"greek\">γέγραπται</span>) 1 Cor 16:21; Col 4:18; 2 Th 3:17 (sobre a conclusão de uma carta escrita de próprio punho pelo remetente, nas cartas em papiro assim como nas obras do imperador Juliano [Epistulae, Leges etc., ed. Bidez e Cumont 1922, n.os 9; 11], v. CBruns, Die Unterschriften in den röm. Rechtsurkunden: ABA 1876, 41–138; KDziatzko, verbete Brief: Pauly-W. III 1899, 836ff; Dssm., LO 132f; 137f [LAE 166f; 171f]; v. também a literatura s.v. <span class=\"greek\">χαίρω</span> 2b). <span class=\"greek\">ἐννεύω</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">χ</span>. (v. <span class=\"greek\">ἐννεύω</span>). <span class=\"greek\">κατασείω</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">χ</span>. (v. <span class=\"greek\">κατασείω</span> 2). <span class=\"greek\">κρατέω</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">χ</span>. (<span class=\"greek\">κρατέω</span> 3b). Pl. <span class=\"greek\">ταῖς</span> <span class=\"greek\">χερσίν</span> com as mãos (Demetr. Phaler.: 228 Fgm. 38, 28 Jac. [em Diog. L. 2, 13] <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἰδίαις</span> <span class=\"greek\">χερσίν</span>; Diod S 16, 33, 1 <span class=\"greek\">τ</span>. <span class=\"greek\">ἰδίαις</span> <span class=\"greek\">χ</span>. 17, 17, 7 e outros lugares; Aesop, Fab. 272 P.=425 H.; Herm. Wr. 5, 2) Lk 6:1; 1 Cor 4:12; Eph 4:28; 1 Th 4:11 (v. HPreisker, Das Ethos d. Arbeit im NT ’36); Papias (3:3).—<span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">χειρῶν</span> <span class=\"greek\">τινος</span> v. <span class=\"greek\">ἔργον</span> 3 e Rv 9:20.—Com preposições: a mão sobre a qual ou na qual algo repousa, ou da qual algo procede ou é tomado: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">χειρί</span> Mt 3:12; Lk 3:17. (<span class=\"greek\">ἔχειν</span> <span class=\"greek\">τι</span>) <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">χεῖρας</span> Hv 1, 2, 2. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">χεῖρα</span> Rv 20:1. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">χειρῶν</span> Mt 4:6; Lk 4:11 (ambos Ps 90:12; v. final desta seção). <span class=\"greek\">ἐκ</span> (<span class=\"greek\">τῆς</span>) <span class=\"greek\">χειρός</span> (Diod S 2, 8, 6) Rv 8:4; 10:10. A mão por meio da qual algo se realiza: de divindades <span class=\"greek\">θεοὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">χειρῶν</span> <span class=\"greek\">γινόμενοι</span> deuses que são feitos à mão Ac 19:26 (cf. Just., A I, 20, 5). De um templo terrestre <span class=\"greek\">οἰκοδομητὸς</span> <span class=\"greek\">ναὸς</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">χειρός</span> B 16:7.—Pode estar em vista o braço (como Hes., Theog. 150; Hdt. 2, 121, 5 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὤμῳ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">χεῖρα</span>; Herodas 5, 83 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇσι</span> <span class=\"greek\">χερσὶ</span> <span class=\"greek\">τῇσ</span>’ <span class=\"greek\">ἐμῇσι</span>=em meus braços; Paus. 6, 14, 7; Galen, De Usu Part. 2, 2 vol. I p. 67, 1 Helmreich; Longus 1, 4, 2 <span class=\"greek\">χεῖρες</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὤμους</span> <span class=\"greek\">γυμναί</span>) em <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">χειρῶν</span> <span class=\"greek\">ἀροῦσίν</span> <span class=\"greek\">σε</span> Mt 4:6; Lk 4:11 (ambos Ps 90:12; mas v. acima). O todo pela parte: dedo Lk 15:22.</p><p class=\"entry-text\">② agente atuante, mão (de), extensão fig. de 1. Neste sentido a ênfase recai sobre a pessoa ou coisa como fonte de uma atividade.</p><p class=\"entry-text\">ⓐ O AT (mas cf. Diod S 3, 65, 3 <span class=\"greek\">ταῖς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">γυναικῶν</span> <span class=\"greek\">χερσί</span>=pelas mulheres; Ael. Aristid. 45 p. 70 D.: <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">χειρὸς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">δικαίων</span>; Philostrat., Vi. Apoll. 6, 29; Nicetas Eugen. 7, 165 <span class=\"greek\">χειρὶ</span> <span class=\"greek\">βαρβάρων</span>) tem tendência a falar da atividade de uma pessoa como obra de sua mão; <span class=\"greek\">διὰ</span> <span class=\"greek\">χειρός</span> ([<span class=\"greek\">τῶν</span>] <span class=\"greek\">χειρῶν</span>) <span class=\"greek\">τινος</span> (<span class=\"hebrew\" dir=\"rtl\">בְּיַד</span> <span class=\"hebrew\" dir=\"rtl\">פּ׳</span>) por meio de alguém ou de sua atividade, pela mão de Mk 6:2; Ac 2:23; 5:12; 7:25; 11:30; 14:3; 15:23; 19:11. Também <span class=\"greek\">ἐν</span> <span class=\"greek\">χειρί</span> (PsSol 16:14 <span class=\"greek\">ἐν</span> <span class=\"greek\">χειρὶ</span> <span class=\"greek\">σαπρίας</span> por corrupção; cf. AscIs 2:5 <span class=\"greek\">ἐν</span> <span class=\"greek\">χερσίν</span>) Gal 3:19. Correspondentemente, as mãos podem representar aquele que age <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">ὐπὸ</span> <span class=\"greek\">χειρῶν</span> <span class=\"greek\">ἀνθρωπίνων</span> <span class=\"greek\">θεραπεύεται</span> nem Deus necessita ser servido por seres humanos Ac 17:25.</p><p class=\"entry-text\">ⓑ A mão da divindade significa poder divino (Il. 15, 695; Ael. Aristid. 47, 42 K.=23 p. 455 D.: <span class=\"greek\">ἐν</span> <span class=\"greek\">χερσὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>; LXX; Aristobulus em Eus., PE 8, 10, 1; 7–9 [p. 138 Holladay]; Ezk. Trag. 239 em Eus., PE 9, 29, 14; SibOr 3, 672; 795.—Porphyr. em Eus., PE 4, 23, 6 <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">χεῖρα</span>, subent. <span class=\"greek\">τ</span>. <span class=\"greek\">δαίμονας</span>; Ath. 33, 2 <span class=\"greek\">παραβαίνων</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">χεῖρα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>). V. New Docs 2, 44.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. como Criador (Ath. 34, 1) Ac 7:50 (Is 66:2). <span class=\"greek\">ποίησις</span> <span class=\"greek\">χειρῶν</span> <span class=\"greek\">αὐτοῦ</span> 1 Cl 27:7 (Ps 18:2). <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">χειρῶν</span> <span class=\"greek\">σου</span> Hb 1:10 (Ps 101:26; ApcEsdr 1:10 p. 25, 2 Tdf.); 2:7 v.l. (Ps 8:7). Cf. B 5:10. Em conexão com o relato da criação as palavras <span class=\"greek\">ἄνθρωπον</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἱεραῖς</span> <span class=\"greek\">χερσὶν</span> <span class=\"greek\">ἔπλασεν</span> 1 Cl 33:4 poderiam ser tomadas no sentido lit.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. como governante, auxiliador, realizador de maravilhas, regulador do universo: <span class=\"greek\">χεὶρ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">μετ</span>’ <span class=\"greek\">αὐτοῦ</span> Lk 1:66; Ac 11:21 (TestAbr A 18 p. 100, 21 [Stone p. 48]).—Lk 23:46 (Ps 30:6); J 10:29; Ac 4:28 (com <span class=\"greek\">βουλή</span>, daí quase=‘vontade’; cf. Sir 25:26), 30; 1 Pt 5:6 (cf. Gen 16:9); 1 Cl 60:3. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κραταιὰν</span> <span class=\"greek\">χεῖραν</span> GJs 15:4.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. como aquele que pune (PsSol 5:6 <span class=\"greek\">μὴν</span> <span class=\"greek\">βαρύνῃς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">χεῖρά</span> <span class=\"greek\">σου</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἡμᾶς</span>; escólio a Apollon. Rhod. 4, 1043a <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">χερσὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">νέμεσις</span>) <span class=\"greek\">χεὶρ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">σε</span> (1 Km 12:15) Ac 13:11. <span class=\"greek\">ἐμπεσεῖν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">χεῖρας</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ζῶντος</span> (v. <span class=\"greek\">ἐμπίπτω</span> 2) Hb 10:31. Cf. 1 Cl 28:2.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. da mão poderosa de Cristo ou de um anjo J 3:35; 10:28; 13:3. <span class=\"greek\">ἐκ</span> <span class=\"greek\">χειρὸς</span> <span class=\"greek\">ἀγγέλου</span> GJs 8:1; 13:2; cf. <span class=\"greek\">ἀγγέλων</span> 15:3.—<span class=\"greek\">σὺν</span> <span class=\"greek\">χειρὶ</span> <span class=\"greek\">ἀγγέλου</span> com o auxílio de um anjo Ac 7:35.</p><p class=\"entry-text\">ⓒ poder hostil (Hom. e outros; LXX) <span class=\"greek\">παραδιδόναι</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">χεῖράς</span> <span class=\"greek\">τινος</span> entregar alguém a outrem (ao seu poder) (TestJob 20:3; ParJer 1:6; v. <span class=\"greek\">παραδίδωμι</span> 1b; cf. PsSol 2:7 <span class=\"greek\">ἐγκαταλείπειν</span>; Jos., Ant 6, 273.—B-D-F §217, 2) Ac 21:11b; pass. Mt 17:22; 26:45; Mk 9:31; Lk 9:44; 24:7; Ac 28:17; D 16:4. Também <span class=\"greek\">παραδιδ</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">χειρί</span> <span class=\"greek\">τινος</span> 1 Cl 55:5. <span class=\"greek\">τὸ</span> <span class=\"greek\">αἷμα</span> <span class=\"greek\">σου</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">χεῖράν</span> <span class=\"greek\">μού</span> <span class=\"greek\">ἐστιν</span> teu sangue está em meu poder GJs 23:2; escapar etc. <span class=\"greek\">ἐκ</span> (<span class=\"greek\">τῆς</span>) <span class=\"greek\">χειρός</span> <span class=\"greek\">τινος</span> do poder de alguém (UPZ 79, 18 [159 a.C.] <span class=\"greek\">ἐκπέφευγεν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">χειρός</span> <span class=\"greek\">μου</span>; Gen 32:12; Ex 18:10; Jos., Vi. 83) Lk 1:71, 74; J 10:39; Ac 12:11; AcPl Ha 8, 10f; AcPlCor 1:8. <span class=\"greek\">ἐκ</span> <span class=\"greek\">χειρὸς</span> <span class=\"greek\">σιδήρου</span> <span class=\"greek\">λύσει</span> <span class=\"greek\">σε</span> ele te libertará do poder da espada 1 Cl 56:9 (Job 5:20; Mel., P. 67, 478). <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">χειρῶν</span> <span class=\"greek\">ἡμῶν</span> Ac 24:6 (7) v.l. (cf. X., An. 6, 3, 4; Lucian, Hermot. 9, final). <span class=\"greek\">ἐξέφυγον</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">χεῖρας</span> <span class=\"greek\">αὐτοῦ</span> 2 Cor 11:33 (Diod S 18, 73, 4 <span class=\"greek\">τὰς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Σελεύκου</span> <span class=\"greek\">χεῖρας</span> <span class=\"greek\">διαφυγῶν</span>). <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">χειρὸς</span> <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">παθεῖν</span> B 5:5. <span class=\"greek\">πίε</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ποτήριον</span> … <span class=\"greek\">ἐν</span> <span class=\"greek\">χειροῖν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Ἅιδου</span> bebe o cálice da mão do filho, que está no mundo inferior ApcPtRainer 17f.</p><p class=\"entry-text\">③ combinações preposicionais distintivas: <span class=\"greek\">ἐν</span> <span class=\"greek\">χερσίν</span> de algo que se tem em mãos, com que se está ocupado no momento (Hdt. 1, 35 <span class=\"greek\">τὸν</span> <span class=\"greek\">γάμον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">χερσὶν</span> <span class=\"greek\">ἔχοντος</span>; Appian, Bell. Civ. 5, 81 §342 <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">χερσίν</span>; Ael. Aristid. 45 p. 74 D.; PPetr II, 9 [2], 4 [III a.C.] <span class=\"greek\">ἃ</span> <span class=\"greek\">εἶχον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">χερσίν</span>; Jos., Bell. 43 165) <span class=\"greek\">ἐν</span> <span class=\"greek\">χερσὶν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀγών</span> a competição é nossa preocupação no momento 2 Cl 7:1. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">χεῖρα</span> continuamente (Ps.-Aristot., Mirabilia 52; Jos., Ant. 12, 185) Hv 3, 10, 7; 5:5; m 4, 3, 6 (B-D-F §232, 1.—Nos pap temos o sentido de ‘em particular’, ‘pouco a pouco’: PTebt 71, 15 [II a.C.]; Gnomon [=BGU V] prooem. 2f; PAmh 136, 17).—KGrayston, The Significance of ‘Hand’ in the NT: B Rigaux Festschr. ’70, 479–87.—B. 237ff. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0386-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειραγωγέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χειραγωγέω</span> (<span class=\"greek\">χεῖρ</span>, <span class=\"greek\">ἄγω</span>; Diod S 13, 20, 4; Plut., Maximus Tyr., Lucian e outros; UPZ 110, 55 [164 a.C.]; Judg 16:26 A; Tob 11:16 S; Jos., Ant. 5, 315) tomar/conduzir pela mão (p. ex. uma pessoa subitamente cegada por uma flecha: Appian, Bell. Civ. 2, 60 §248; uma pessoa cega em geral: Artem. 5, 20) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:8.</a> Pass. 22:11; GPt 10:40.—M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0386-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειραγωγός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χειραγωγός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> aquele que conduz outro pela mão, guia (Plut., Mor. 794d; 1063b; Artem. 1, 48; Ael. Aristid. 45 p. 60 D.; Maximus Tyr. 8, 7h [de Deus]; Longus 4, 24, 2; Herm. Wr. 7, 2a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:11.</a>—M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0386-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειρόγραφον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χειρόγραφον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (desde Polyb. 30, 8, 4; SIG 742, 50f [85 a.C.]. Frequentemente nos pap desde II a.C. [p. ex. PYadin 5a I, 9]; Tob) documento manuscrito, especificamente certificado de dívida, conta, registro de dívidas (assim claramente TestJob 11:11; Vi. Aesopi G 122 P.—Dssm., LO 281ff [LAE 332ff]) <span class=\"greek\">τὸ</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">χειρόγραφον</span> a conta que estava contra nós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:14</a> (v. GMegas, ZNW 27, 1928, 305–20; OBlanchette, CBQ 23, ’61, 306–12: identifica o <span class=\"greek\">χ</span>. com Cristo; sobre essas e outras opiniões RYates, Biblica 71, ’90, 251).—DELG s.v. <span class=\"greek\">χείρ</span>. M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0386-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειροποίητος, ον</h1><div class=\"entry-meta\"><span>adjetivo; substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χειροποίητος</span>, <span class=\"greek\">ον</span> (Hdt.+; Diod S 13, 82, 5; 15, 93, 4; 17, 71, 7; Arrian, Anab. 4, 28, 3; PLond III, 854, 4 p. 205 [I d.C.]; LXX; Jos., Bell. 1, 419, Ant. 4, 55; SibOr 3, 606; 618, Fgm. 3, 29; Jos., Bell. 1, 419; Ant. 4, 55; Just.) feito por mãos humanas, de edificações, especificamente templos (SibOr 14, 62 <span class=\"greek\">ναῶν</span> <span class=\"greek\">χειροποιήτων</span>; Philo, Mos. 2, 88 <span class=\"greek\">ἱερόν</span> do tabernáculo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.58\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:58</a>; Ac 7:48 v.l.; 17:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:11,</a> 24. Subst. (ViJer 7 [Sch. p. 10]; Philo, Mos. 2, 168; Just., A I, 58, 3; D. 35, 6) <span class=\"greek\">χειροποίητα</span> templos construídos por mãos humanas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.48\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:48.</a> Da circuncisão física (em oposição à ‘circuncisão do coração’) <span class=\"greek\">τῆς</span> <span class=\"greek\">λεγομένης</span> <span class=\"greek\">περιτομῆς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">χειροποιήτου</span> da assim chamada circuncisão, efetuada na carne por mãos humanas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:11.</a>—DELG s.v. <span class=\"greek\">χείρ</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0386-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειροτονέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χειροτονέω</span> (<span class=\"greek\">τείνω</span>) 1.º aor. <span class=\"greek\">ἐχειροτόνησα</span>, pass. <span class=\"greek\">ἐχειροτονήθην</span> (Aristoph., X., Pla. e outros; ins, pap; Philo, Somn. 2, 243, Spec. Leg. 1, 78; Jos., Vi. 341 e outros lugares; Just., D. 108, 2) lit. ‘estender a mão’ na votação</p><p class=\"entry-text\">① eleger ou escolher alguém para determinados ofícios ou tarefas, escolher (IG IV2/1, 89, 18 [II/III d.C.] <span class=\"greek\">χ</span>. <span class=\"greek\">ἱερέας</span>; Jos. Ant. 13.45). As congregações escolhem um representante para acompanhar Paulo em sua viagem a fim de levar a coleta a Jerusalém 2 Cor 8:19 (IG II2/1, 1260 <span class=\"greek\">χειροτονηθεὶς</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">δήμου</span> <span class=\"greek\">στρατηγός</span>.—V. Windisch ad loc.; Betz, 2 Cor p. 74f). As congregações escolhem emissários para levar congratulações à <span class=\"greek\">ἐκκλησία</span> em Antioquia IPhld 10:1; ISm 11:2; IPol 7:2. As congregações devem eleger seus próprios supervisores (<span class=\"greek\">ἐπίσκοποι</span>) e ministros (<span class=\"greek\">διάκονοι</span>) D 15:1.</p><p class=\"entry-text\">② Por outro lado, os presbíteros (<span class=\"greek\">πρεσβύτεροι</span>) na Licaônia e na Pisídia não foram escolhidos pelas congregações, mas se diz de Paulo e Barnabé <span class=\"greek\">χειροτονήσαντες</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐκκλησίαν</span> <span class=\"greek\">πρεσβυτέρους</span> Ac 14:23. Cf. Tit 1:9 v.l. e subscrição; 2 Ti subscrição. Isso não envolve uma escolha pelo grupo; aqui a palavra significa nomear, investir no cargo, com os apóstolos como suj. (Philo, Praem. 54 <span class=\"greek\">βασιλεὺς</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">χειροτονηθείς</span>, De Jos. 248 José <span class=\"greek\">βασιλέως</span> <span class=\"greek\">ὕπαρχος</span> <span class=\"greek\">ἐχειροτονεῖτο</span>, Mos. 1, 198, In Flacc. 109; Jos., Ant. 6, 312 <span class=\"greek\">τὸν</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">κεχειροτονημένον</span> <span class=\"greek\">βασιλέα</span>; 13, 45). JRoss, ET 63, ’51f, 288f; ELohse, D. Ordination im Spätjudentum u. im NT, ’51; MWarkentin, Ordination ’82.—Kl. Pauly I 1142. New Docs 1, 123. DELG s.v. <span class=\"greek\">χείρ</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0386-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειροτονία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χειροτονία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (Thu. e outros; ins, pap, Philo; Jos., Bell. 4, 147, Ant. 3, 192 de escolher e eleger; v. <span class=\"greek\">χειροτονέω</span>) lit. ‘estender a mão’; em nossa literatura somente uma vez e no sentido de levantar a mão como gesto hostil ou de desprezo, gesto de desprezo <span class=\"greek\">ἐὰν</span> <span class=\"greek\">ἀφέλῃς</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">σοῦ</span> <span class=\"greek\">χειροτονίαν</span> se deixares de levantar a mão B 3:5 (Is 58:9).—DELG s.v. <span class=\"greek\">χείρ</span>. M-M s.v. <span class=\"greek\">χειροτονέω</span>. DNP II 1114. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0386-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χείρων, ον, gen. ονος</h1><div class=\"entry-meta\"><span>adjetivo comparativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χείρων</span>, <span class=\"greek\">ον</span>, gen. <span class=\"greek\">ονος</span> (Hom. e outros; pap, LXX; JosAs 1:13; GrBar, Philo, Joseph.) pl. masc., fem. <span class=\"greek\">χείρους</span> (Just., D. 1, 5; Ath. 31, 1) comp. de <span class=\"greek\">κακός</span>, superl. <span class=\"greek\">χείριστος</span> LXX; adv. <span class=\"greek\">χεῖρον</span> (GrBar 4:16), <span class=\"greek\">χείριστα</span> (2 Macc 5:23) pior, mais grave <span class=\"greek\">σχίσμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:21.</a> <span class=\"greek\">τιμωρία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:29</a> (Jos., Vi. 172; cf. PGM 2, 54). <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">χεῖρόν</span> <span class=\"greek\">σοί</span> <span class=\"greek\">τι</span> <span class=\"greek\">γένηται</span> para que nada pior te aconteça <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:14</a> (cf. Jos., Ant. 4, 142). Com gen. de comparação (1 Km 17:43; Wsd 15:18) <span class=\"greek\">γίνεται</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔσχατα</span> <span class=\"greek\">χείρονα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πρώτων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:20.</a> Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.64\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:64.</a>—De uma mulher enferma <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">χεῖρον</span> <span class=\"greek\">ἐλθεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:26.</a>—No domínio moral Hs 9, 17, 5; 9, 18, 1. Com gen. de comparação (LXX, JosAs; GrBar 4:16; Ar. 8, 2; Just., A II, 3, 3) <span class=\"greek\">ἀπίστου</span> <span class=\"greek\">χείρων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:8.</a> <span class=\"greek\">προκόπτειν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">χεῖρον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:13</a> (<span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">χ</span>. como X., Mem. 3, 5, 13; Pla., Rep. 381b; Diod S 15, 88, 4; Strabo 16, 2, 39; Artem. 1, 74 p. 67, 11; UPZ 110, 124 [164 a.C.]; Jos., Ant. 16, 207). Os cristãos nada sabem de uma <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κρειττόνων</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">χείρω</span> <span class=\"greek\">μετάνοια</span> MPol 11:1 (Maximus Tyr. 5, 3a <span class=\"greek\">εἰ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">χεῖρον</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βελτίστου</span>, <span class=\"greek\">πονερῶς</span> [sic] <span class=\"greek\">μετέθετο</span>=se [um homem passa] do melhor para o pior, então a mudança que faz é má). De um destacamento militar comparado a feras <span class=\"greek\">οἳ</span> <span class=\"greek\">χείρους</span> <span class=\"greek\">γίνονται</span> que (simplesmente) se tornam tanto mais violentos quanto mais bondosamente são tratados IRo 5:1 (cf. Philo, Abr. 129).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0386-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Χερούβ, τό / ὁ</h1><div class=\"entry-meta\"><span>substantivo indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Χερούβ</span>, <span class=\"greek\">τό</span> (Ezk 28:16) e <span class=\"greek\">ὁ</span> (Ex 25:19; 38:7: <span class=\"hebrew\" dir=\"rtl\">כְּרוּב</span>) indecl. a imagem da criatura alada que se encontrava sobre a arca da aliança, criatura alada, o pl. com várias terminações <span class=\"greek\">Χερουβίν</span>,-<span class=\"greek\">βείν</span> (En 20:7; PGM 13, 255; 334),-<span class=\"greek\">βείμ</span>,-<span class=\"greek\">βίμ</span> (TestSol, TestAbrB; TestJob 50:2; ApcEsdr 2:26 p. 26, 20 Tdf. e outros lugares; ApcMos; SibOr 3, 1 <span class=\"greek\">τὰ</span> <span class=\"greek\">Χερουβίμ</span>; En 14:11 <span class=\"greek\">Χερουβὶν</span> <span class=\"greek\">πύρινα</span>; PGM 7, 634 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">Χερουβίν</span>; IDefixWünsch 3, 24 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Χερουβί</span>; Ps 79:2 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Χερουβίν</span>; En 20:7 <span class=\"greek\">Χερουβείν</span>.—Como sing. PGM 4, 3061 <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χερουβίν</span>; 7, 264 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">Χερουβίν</span>), predominantemente neut. <span class=\"greek\">τά</span> (Gen 3:24; Ex 25:18; 3 Km 6:27f; 8:7; 2 Ch 3:10, 13; Ezk 10:3, 8, 15; 11:22; 41:18, 20; En 14:11; ApcSed 2:26; ApcMos 19; Philo, Cher. 1; 25; 28, Fuga 100) mais raramente masc. <span class=\"greek\">οἱ</span> (Ex 25:19; 38:6f; Jos., Ant. 3, 137.—Em outros lugares Joseph. escreve <span class=\"greek\">Χερουβεῖς</span>; com efeito, empregou a palavra como masc., Ant. 7, 378 e como fem. 8, 72f), das duas figuras aladas sobre a arca da aliança <span class=\"greek\">Χερουβὶν</span> <span class=\"greek\">δόξης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:5.</a>—AJacoby, ARW 22, 1924, 257–65; PDhorme/LVincent, Les Chérubins: RB 35, 1926, 328–58; 481–95; TLL, Suppl. 1, 389–92.—BHHW I 298f. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0386-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χερσόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χερσόω</span> (<span class=\"greek\">χέρσος</span> ‘terra seca’; Hom. e outros) tornar seco e estéril (BGU 195, 21 [II d.C.]) em nossa literatura (Hermas) somente pass. <span class=\"greek\">χερσόομαι</span> (Strabo 17, 1, 36; IGR IV, 147; PTebt 5, 94 [118 a.C.]; 61b, 30; 75, 40; LXX) 1.º aor. <span class=\"greek\">ἐχερσώθην</span>; partic. perf. <span class=\"greek\">κεχερσωμένος</span> tornar-se estéril ou inculto, lit. de vinhas sem cultivo Hm 10, 1, 5. Fig. de cristãos que estão enredados com o mundo 10, 1, 4 ou que negam seu Senhor Hs 9, 26, 3.—DELG s.v. <span class=\"greek\">χέρσος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0386-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χέω</span> (Hom. e outros; ins, pap, LXX; TestLevi 18:5 [início]) fut. 3.ª sg. <span class=\"greek\">χεεῖ</span> Mal 3:3. Pass.: fut. 3.ª sg. <span class=\"greek\">χυθήσεται</span> Jon 2:2; partic. aor. gen. <span class=\"greek\">χυθέντος</span> (Mel., P. 30, 207); perf. 3.ª sg. <span class=\"greek\">κέχυται</span> e partic. <span class=\"greek\">κεχυμένος</span> LXX; em sua única ocorrência em nossa literatura está na média e pass. <span class=\"greek\">χέομαι</span> derramar-se, jorrar (Philo, Spec. Leg. 4, 26; Jos., Ant. 8, 232; SibOr, Fgm. 3, 33) <span class=\"greek\">ταῦτα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">χεόμενα</span> <span class=\"greek\">ὕδατα</span> das águas do tanque de Davi, em contraste com as águas da vida eterna Ox 840, 32.—B. 577. DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0386-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χήρα, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χήρα</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (Hom.+) mulher cujo marido morreu, viúva</p><p class=\"entry-text\">ⓐ de uma viúva como tal (com e sem <span class=\"greek\">γυνή</span>)—<span class=\"greek\">γυνὴ</span> <span class=\"greek\">χήρα</span> (Hom. e outros; BGU 522, 7; POxy 1120, 12; Jos., Ant. 4, 240; 8, 320; LXX) uma viúva Lk 4:26 (segundo 3 Km 17:9). Em outros lugares <span class=\"greek\">ἡ</span> <span class=\"greek\">χήρα</span> somente, viúva (Hom.; Soph., Aj. 653; Eur.+; ins, pap, LXX, TestJob; SibOr 3, 77; Philo; Jos., Ant. 16, 221; Ar. 15, 7; Just.); a ideia de necessidade é frequentemente associada a essa palavra, e ela é frequentemente unida à de órfãos (<span class=\"greek\">ὀρφανός</span> 1) Mt 23:13 (14) v.l.; Mk 12:40, 42f (HHaas, ‘Das Scherflein d. Witwe’ u. seine Entsprechung im Tripitaka 1922); Lk 2:37; 4:25; 7:12; 18:3, 5; 20:47 (JRoth, The Blind, The Lame, and the Poor, diss. Vanderbilt ’94, especialmente 320ff); 21:2f; Ac 6:1 (cf. X., Oec. 7, 42f sobre mulheres idosas que perdem a estima); 9:39, 41; 1 Cor 7:8; 1 Ti 5:4, 11 (sobre a idade relativamente jovem [c. 30 anos no mundo helênico] v. referências bibliográficas e de inscrições SEG XLIII, 1331), 16a; Js 1:27; 1 Cl 8:4 (Is 1:17); B 20:2; 1 Sm 6:2; IPol 4:1; Pol 6:1; Hv 2, 4, 3; m 8:10; Hs 1:8; 5, 3, 7; 9, 26, 2; 9, 27, 2; GJs 4:4. <span class=\"greek\">ἡ</span> <span class=\"greek\">ὄντως</span> <span class=\"greek\">χήρα</span> a verdadeira viúva (<span class=\"greek\">ὄντως</span> b) 1 Ti 5:3b, 5, 16b.—Metaf., nas palavras orgulhosas da prostituta da Babilônia <span class=\"greek\">κάθημαι</span> <span class=\"greek\">βασίλισσα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">χήρα</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">εἰμί</span> Rv 18:7 (cf. La 1:1).</p><p class=\"entry-text\">ⓑ de uma classe especial nas comunidades cristãs, à qual somente podiam pertencer viúvas que satisfizessem determinados requisitos. Era necessário ser <span class=\"greek\">ὄντως</span> <span class=\"greek\">χήρα</span> (v. 1 acima) 1 Ti 5:3, 9; ISm 13:1 (v. <span class=\"greek\">παρθένος</span> a); Pol 4:3.—Sobre as viúvas nas igrejas v. LZscharnack, Der Dienst der Frau 1902, 100ff; ABludau, D. Versorgung der Witwen (1 Ti 5:3–16): Der kathol. Seelsorger 19, 1907, 165–67; 204–11; 255–60; 305–10; 350–53; ALudwig, Weibl. Kleriker: Theolog.-prakt. Monatsschrift 20, 1910, 548–57; 609–17; EvdGoltz, D. Dienst d. Frau in d. christl. Kirche2 1914; JViteau, L’institution des Diacres et des Veuves: Revue d’ Hist. ecclés. 22, 1926, 513–36; AKalsbach, D. Altkirchl. Einrichtung d. Diakonissen 1926; JMüller-Bardoff, EFascher Festschr. ’58, 113–33; L-MGünther, Witwen in der griechischen Antike, Zwischen Oikos und Polis: Historia 42, ’93, 308–25; FSpencer, CBQ 56, ’94, 715–34; RPrice, The Widow Traditions in Luke-Acts (SBLDS 155) ’97.—V. também s.v. <span class=\"greek\">γυνή</span> 1.—B. 131. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0386-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χηρεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χηρεία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">χήρα</span>; Thu. e outros; ins, pap, LXX, Philo) viuvez GJs 2:1 v.l. (em lugar de <span class=\"greek\">χηροσύνη</span>).—DELG s.v. <span class=\"greek\">χήρα</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0386-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χηρεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χηρεύω</span> (<span class=\"greek\">χήρα</span>) fut. 3.ª sg. <span class=\"greek\">χηρεύσει</span> (SibOr 2, 206); aor. 3.ª sg. <span class=\"greek\">ἐχήρευσε</span> Jer 28:5 (Hom., Od. 9, 124; Isaeus, Demosth., LXX; TestJud 12:1f; SibOr, Philo) lit. ‘estar vazio’, depois estar viúvo <span class=\"greek\">τοὺς</span> <span class=\"greek\">χηρεύοντας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">λαοῦ</span> GJs 8:3.—DELG s.v. <span class=\"greek\">χήρα</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0386-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χηροσύνη</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χηροσύνη</span> (<span class=\"greek\">χήρα</span>; Appolon. Rhod.; Manetho, Apotelesmatica) lit. condição de privação ou perda de ente querido, depois viuvez <span class=\"greek\">κόψομαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">χηροσύνην</span> <span class=\"greek\">μου</span> lamentarei minha viuvez GJs 2:1.—DELG s.v. <span class=\"greek\">χήρα</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0386-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χθές</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χθές</span> (Hom. Hymns e outros; a verdadeira forma ática; PSI 184, 5 [III d.C.]; PLond III, 983, 2 p. 229 [IV d.C.]; Jos., Ant. 6, 126, C. Ap. 1, 7; TestNapht 1:4; Ath., Just.) ontem=<span class=\"greek\">ἐχθές</span> (v. esse verbete) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.52\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:52</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:28</a> v.l. (Ex 2:14 v.l.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:8</a> v.l. (do passado [v. <span class=\"greek\">ἐχθές</span>] como Diod S 2, 5, 5; Jos., Ant. 18, 243; Celsus 6, 10).—B. 1000. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0386-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιϚ´</h1><div class=\"entry-meta\"><span>sinal numérico; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χιϚ</span>´ v. <span class=\"greek\">χξϚ</span>´.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0386-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιλίαρχος, ου, ὁ / χιλιάρχης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χιλίαρχος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> e <span class=\"greek\">χιλιάρχης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">χίλιοι</span>, <span class=\"greek\">ἄρχω</span>; Aeschyl., X.+; ins, pap, LXX; Jos., Ant. 7, 368; 12, 301; empréstimo na literatura rabínica) lit. ‘comandante de mil soldados’, depois também=o romano tribunus militum, tribuno militar, o comandante de uma coorte=aproximadamente 600 homens (assim desde Polyb. 1, 23, 1; 6, 19, 1; 7ff; também Polyaenus 7, 17; Jos., Ant. 17, 215; ins, pap; v. Hahn 47; 116; 168; Mason 99), neste sentido (aproximadamente equivalente a major ou coronel) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:12</a>; Ac 21:31–33, 37; 22:24, 26–29; 23:10, 15, 17–19, 22; 24:7, 22; 25:23; 1 Cl 37:3.—De oficiais militares de alta patente em geral <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:21</a> (mas v. EKlostermann, Hdb. ad loc.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:15</a>; 19:18.—<span class=\"greek\">χιλιάρχης</span> (em lugar de <span class=\"greek\">ἐκατόναρχος</span>,-<span class=\"greek\">χης</span>) vv.ll. Mt 8:5, 8, 13. V. a literatura s.v. <span class=\"greek\">ἐκατοντάρχης</span>.—DELG s.v. <span class=\"greek\">χίλιοι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0386-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιλιάς, άδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χιλιάς</span>, <span class=\"greek\">άδος</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">χίλιοι</span>; Aeschyl., Hdt.+; LXX; TestSol 26:9 H; TestAbr, TestJob, JosAs; GrBar 4:10) grupo de mil, milhar, pl. (En 10:17, 19; Jos., Ant. 6, 193) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:31ab</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:8</a>; Rv 7:4–8; 11:13; 14:1, 3; 21:16; 1 Cl 43:5. <span class=\"greek\">χίλιαι</span> <span class=\"greek\">χιλιάδες</span> 34:6 (Da 7:10). <span class=\"greek\">χιλιάδες</span> <span class=\"greek\">χιλιάδων</span> milhares sobre milhares <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:11</a> (<span class=\"greek\">χιλιάδων</span> também empréstimo na literatura rabínica). Em Rv o substantivo que designa aquilo que é contado pode estar no mesmo caso de <span class=\"greek\">χιλ</span>. (assim Theophanes Conf., Chron. 482, 14 deBoor <span class=\"greek\">λ</span>´ <span class=\"greek\">χιλιάδες</span> <span class=\"greek\">νομίσματα</span>; 7, 17 <span class=\"greek\">πολλὰς</span> <span class=\"greek\">μυριάδας</span> <span class=\"greek\">μάρτυρας</span>) em lugar do gen. 7:4, 5a, 8c; 11:13; cf. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">σταδίων</span> <span class=\"greek\">δώδεκα</span> <span class=\"greek\">χιλιάδων</span> 21:16 (<span class=\"greek\">ἐπὶ</span> <span class=\"greek\">σταδίους</span> <span class=\"greek\">δώδεκα</span> <span class=\"greek\">χιλιάδων</span> v.l.). O milênio <span class=\"greek\">χιλιάδα</span> <span class=\"greek\">τινὰ</span> … <span class=\"greek\">ἐτῶν</span> <span class=\"greek\">ἔσεσθαι</span> Papias (2:12).—DELG s.v. <span class=\"greek\">χίλιοι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0386-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χίλιοι, αι, α</h1><div class=\"entry-meta\"><span>numeral cardinal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χίλιοι</span>, <span class=\"greek\">αι</span>, <span class=\"greek\">α</span>(Hom.+; ins, pap, LXX, Philo; Jos., Bell. 1, 317; Ant; Jos., Bell. 1, 317, Ant. 11, 15, Vi. 95 e outros lugares; TestJob 32:3; TestJud 4:1; 9:8; Just.; empréstimo na literatura rabínica) mil <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:8ab</a> (Ps 89:4); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:3</a>; 12:6; 14:20; 1 Cl 34:6 (Da 7:10; v. <span class=\"greek\">χιλιάς</span>); B 15:4 (Ps 89:4). O milênio Rv 20:2–7 (Just., D. 80, 5; 81, 3; concepções intertestamentárias JBailey, JBL 53, ’34, 170–87.—LGry, Le Millénarisme dans ses origines et son développement 1904; JSickenberger, Das Tausendjährige Reich in Apk: SMerkle Festschr. 1922, 300–316; AWikenhauser, D. Problem d. 1000jähr. Reiches in Apk: Röm. Quartalschr. 40, ’32, 13–25, D. Herkunft der Idee des 1000j. R. in Apk: ibid. 45, ’38, 1–24, também TQ 127, ’47, 399–417; HBietenhard, D. 1000j. Reich ’55).—DELG. EDNT. TW.</p></section></article>"};
